<?php
declare(strict_types=1);
$page_title='Review Loan Application'; require __DIR__.'/../../includes/header.php'; require_admin();
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT); if(!$id) { http_response_code(404); exit('Application not found.'); }
$stmt=$pdo->prepare("SELECT a.*, CONCAT(u.first_name,' ',u.last_name) customer_name,u.phone,u.email,u.national_id,u.address,u.monthly_income customer_income,p.name product_name,p.interest_rate,p.interest_type,p.processing_fee,p.late_fee FROM loan_applications a JOIN users u ON u.id=a.customer_id JOIN loan_products p ON p.id=a.loan_product_id WHERE a.id=? LIMIT 1");$stmt->execute([$id]);$a=$stmt->fetch(); if(!$a){http_response_code(404);exit('Application not found.');}
?>
<div class="card"><h1>Application <?=e($a['application_no'])?></h1><div class="form-grid"><div><strong>Customer</strong><p><?=e($a['customer_name'])?><br><?=e($a['phone'])?><br><?=e((string)$a['email'])?></p></div><div><strong>Product</strong><p><?=e($a['product_name'])?><br>Interest: <?=e((string)$a['interest_rate'])?>% (<?=e($a['interest_type'])?>)<br>Fee: <?=money((float)$a['processing_fee'])?></p></div><div><strong>Requested amount</strong><p><?=money((float)$a['requested_amount'])?></p></div><div><strong>Term</strong><p><?=e((string)$a['requested_term_months'])?> months</p></div><div><strong>Monthly income</strong><p><?=money((float)$a['monthly_income'])?></p></div><div><strong>Submitted</strong><p><?=e($a['requested_date'])?></p></div></div><hr><strong>Purpose</strong><p><?=nl2br(e($a['purpose']))?></p><strong>Employment / income details</strong><p><?=nl2br(e($a['employment_details']))?></p></div>
<?php if(in_array($a['status'],['pending','under_review'],true)): ?>
<div class="card" style="margin-top:20px"><h2>Review decision</h2><form action="/primelend_zambia/actions/application_review_process.php" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="application_id" value="<?= (int)$a['id'] ?>"><div class="form-grid"><div><label>Decision</label><select name="decision" required><option value="under_review">Mark Under Review</option><option value="approve">Approve</option><option value="reject">Reject</option></select></div><div><label>Admin notes / rejection reason</label><textarea name="notes" maxlength="3000"></textarea></div></div><p><button class="button" type="submit">Save Decision</button></p></form></div>
<?php endif; ?>
